import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.DaCm-iTo.js";const h=JSON.parse('{"title":"事件 API","description":"","frontmatter":{},"headers":[],"relativePath":"modules/level/events.md","filePath":"modules/level/events.md","lastUpdated":null}'),r={name:"modules/level/events.md"};function l(n,t,c,s,i,p){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="事件-api" tabindex="-1">事件 API <a class="header-anchor" href="#事件-api" aria-label="Permalink to &quot;事件 API&quot;">​</a></h1><p>Level 当前有 5 个同步 Bukkit 事件。runtime 只在当前线程拥有在线玩家时发布；公开同步写 API 对错误线程返回 <code>WRONG_THREAD</code>。</p><table tabindex="0"><thead><tr><th>事件</th><th>触发时机</th><th>Cancellable</th><th>可修改字段</th><th>取消/结果效果</th></tr></thead><tbody><tr><td><code>PlayerExpGainEvent</code></td><td>倍率/日上限调整后、经验和日配额写入前</td><td>是</td><td><code>amount</code></td><td>取消或最终 <code>&lt;=0</code> 阻止经验与配额消耗；正数仍受剩余配额限制</td></tr><tr><td><code>PlayerPreLevelUpEvent</code></td><td>全部校验后、journal/扣费/等级/奖励/actions 前</td><td>是</td><td>无</td><td>阻止整次 level-up transaction</td></tr><tr><td><code>PlayerLevelUpEvent</code></td><td>经验驱动升级、奖励与 success actions 提交后</td><td>否</td><td>无</td><td>post，不可回滚</td></tr><tr><td><code>PlayerMaxLevelReachedEvent</code></td><td>经验驱动升级首次跨到配置上限后</td><td>否</td><td>无</td><td>milestone post；直接 <code>setLevel</code> 不属于此路径</td></tr><tr><td><code>PlayerLevelChangeEvent</code></td><td>add/remove/set/reset 等管理型等级变更实际提交后</td><td>否</td><td>无</td><td>post；不替代经验驱动 <code>PlayerLevelUpEvent</code></td></tr></tbody></table><p>所有事件均在玩家 owner thread。事件表示内存 transaction 的对应阶段，不保证异步持久化已经落盘。监听器不得阻塞等待 I/O；跨玩家工作应分别重新调度。</p>',4)])])}const _=e(r,[["render",l]]);export{h as __pageData,_ as default};
